import { RoutePlayback, RoutePlaybackDisposedError } from "./route-playback.js";
export function createSessionRoutePlayback(opts) {
    const assertCurrentGeneration = ()=>{
        if (opts.generation !== opts.getGeneration()) {
            throw new RoutePlaybackDisposedError("device session changed during route playback");
        }
    };
    return new RoutePlayback({
        applyLocation: async (fix, signal)=>{
            assertCurrentGeneration();
            await opts.applyLocation(opts.serial, fix, signal);
            assertCurrentGeneration();
        },
        onLocation: (fix)=>{
            if (opts.generation === opts.getGeneration()) opts.onLocation(fix);
        },
        ...opts.clock ? {
            clock: opts.clock
        } : {}
    });
}
